"""Create local owner review overview from saved revision evidence."""
from pathlib import Path
from PIL import Image,ImageDraw
import json,hashlib
ROOT=Path(__file__).resolve().parents[2];LIB=ROOT/'assets/art-library';review=LIB/'shipyard-equipment'
jobs=json.loads((ROOT/'.runtime/art-library/equipment/jobs.json').read_text())
board=Image.new('RGB',(1800,880),'#142a36');draw=ImageDraw.Draw(board)
edges=Image.new('RGB',(1800,760),'white');ed=ImageDraw.Draw(edges)
lines=['# Shipyard equipment — Blender review set','','**10 catalog assets · 9 canonical designs · 17 original placements · 9 owner-approved exact revisions · installed.**','','These revisions preserve native authored Blender surfaces and emissive PBR materials in the visual GLB. Validated occupancy proxies remain separate. The catalog and both applications now load these approved native GLBs. Placement identities, transforms and occupancy data remain unchanged. Older source files are retained.','','![Current Blender review board](current-review-board.png)','','[Exact inventory and source trace](inventory.json) · [Measured export validation](validation.json) · [Actual placement occupancy audit](placement-fit.json) · [First preserved review board](first-review-board.png)','','## Current revisions','','| Design | Revision | Blender / reference comparison | Actual Shipyard | Status |','| --- | --- | --- | --- | --- |']
i=0
for j in jobs:
 ledger=json.loads((LIB/'designs'/j['design_id']/'design.json').read_text());r=f"r{j['revision']:03}";relative=f"../designs/{j['design_id']}/revisions/{r}"
 lines.append(f"| [{j['slug']}](../designs/{j['design_id']}/DESIGN.md) | {r} | [Comparison]({relative}/comparison.png) · [Source]({relative}/blender-source.blend) | [Close]({relative}/runtime-close.png) · [Top]({relative}/runtime-top.png) · [Lighting]({relative}/runtime-context.png) | {ledger['state']} |")
 for v in j['variants']:
  path=ROOT/j['output']/v['name']/'cutout.png';src=Image.open(path).convert('RGBA');src.thumbnail((350,355));x=(i%5)*360;y=(i//5)*420
  board.paste(src,(x+(360-src.width)//2,y+48),src);draw.text((x+12,y+10),j['slug']+' / '+v['name'],fill='white');draw.text((x+12,y+28),r+' - approved',fill='#87cddd')
  small=Image.open(path).convert('RGBA');small.thumbnail((175,300));x=(i%5)*360;y=(i//5)*380
  ed.rectangle((x,y,x+180,y+380),fill='#f5f1e8');ed.rectangle((x+180,y,x+360,y+380),fill='#111f2c');edges.paste(small,(x+(180-small.width)//2,y+40),small);edges.paste(small,(x+180+(180-small.width)//2,y+40),small);ed.text((x+6,y+8),j['slug'],fill='#142a36');i+=1
board.save(review/'current-review-board.png');edges.save(review/'alpha-edge-review.png')
lines += ['', '## Evidence and remaining review', '', 'Each revision retains editable Blender meshes and the evaluated native visual mesh, GLB, real RGBA cutout, Blender close/top renders, actual Shipyard close/top screenshots, dark fixture-off/on diagnostics, reference/previous/current comparison, measured validation, capture context and reproducible recipe archive. The bridge-bank archive additionally retains the complete starboard source/export/render/capture set; both catalog IDs remain distinct.', '', 'The per-revision screenshots retain the original review capture using browser-only asset routing. [Installation evidence](installation.md) shows the actual game and Shipyard loading the installed assets. The selected original placement is recentered for inspection. Overhead views use a recorded review camera override. These are not published installs, full in-ship walkthroughs or proof of animated crew fit.', '', 'The visual set passes original-envelope checks; the separate retained voxel proxies pass occupied-cell placement checks for all 17 equipment placements. Crew clearance, ports and stats are explicitly proposed; animated rig fit, mechanical motion and authoritative functionality remain unimplemented acceptance work. Remaining visual differences are documented separately for every design.', '', 'Native curves and leaf edges now survive export. Proxy cells do not represent every visual detail; local voxel damage remeshing still loses authored detail and remains a migration limitation. Runtime fixtures use at most two spotlights per equipped placement and affect that placement only; emissive materials remain in the GLB. Fixture lighting casts no runtime shadows yet. No optical glass or transmission is flattened into opaque material.', '', '[Alpha edges on light and dark backgrounds](alpha-edge-review.png).', '', '## Validation checkpoint', '', '- Full build, art checks, library invariant tests/typecheck and document checks pass.', '- Current general check and fixture tests pass. [Saved gate logs](verification.json).', '- The normal art:voxels command writes published runtime/source outputs. Per the owner’s review-only instruction, this detail pass exports native Blender surfaces and validates the retained separate proxies with the actual voxel placement validator.', '', '## Reproduce in a fresh review revision', '', '`npm run art:library:equipment -- .runtime/art-library/equipment/NEW-jobs.json --native-detail` refines authored Blender sources and exports native GLBs. Job manifests must point to fresh isolated review directories and explicit prior sources. Never overwrite retained evidence. `npm run art:library:equipment:fit` is a read-only proxy fixture audit.', '', 'The saved recipe archives include the exact Blender recipe, runtime lighting helper, source, separate proxy, job and browser capture script for that revision. Copied source geometry retains its prior recipe history. The current index is a generated review overview; design.json remains the living canonical ledger.', '', '## Owner feedback', '', 'Recorded owner direction: “You should work with the blender path. Typescript voxel solids for all equipment is being phased out.” This is implemented by the source workflow. The owner requested more reference detail, especially the medical bed, emissive screens and correctly located grow lighting. This feedback is recorded against the previous exact revisions. The owner subsequently approved these exact revisions and authorized their implementation in the game; see [publication record](publication.json). Future changes require a new revision and review. Proposed gameplay statistics remain separate from this visual approval.']
(review/'README.md').write_text('\n'.join(lines)+'\n')
